(x, y, a, b, c, d, xs, ys, t, maxx) = [0] * 10
arr = []

def abs(x):
	if x < 0:
		return 0 - x
	return x

def max(x, y):
	if x > y:
		return x
	return y

def dfs(idx, left, currx, curry, dir, cnt):
	global arr, maxx
	if dir == 0:
		if idx < 0:
			maxx = max(maxx, cnt)
			return
		elif abs(currx - arr[idx][0]) + abs(curry - arr[idx][1]) <= left:
			dfs(idx - 1, left - (abs(currx - arr[idx][0]) + abs(curry - arr[idx][1])), arr[idx][0], arr[idx][1], 0, cnt + 1)
		else:
			maxx = max(maxx, cnt)
	elif idx >= len(arr):
		maxx = max(maxx, cnt)
		return
	elif abs(currx - arr[idx][0]) + abs(curry - arr[idx][1]) <= left:
		dfs(idx + 1, left - (abs(currx - arr[idx][0]) + abs(curry - arr[idx][1])), arr[idx][0], arr[idx][1], 1, cnt + 1)
	else:
		maxx = max(maxx, cnt)

def main():
	global x, y, a, b, c, d, xs, ys, t, maxx, arr
	(x, y, a, b, c, d) = [int(z) for z in input().split()]
	(xs, ys, t) = [int(z) for z in input().split()]
	arr = [[x, y]]
	maxx = 0
	currx = x
	curry = y
	for i in range(0, 100):
		currx = a * currx + c
		curry = b * curry + d
		arr.append([currx, curry])
	for i in range(0, 100):
		dfs(i, t, xs, ys, 0, 0)
		dfs(i, t, xs, ys, 1, 0)
	print(maxx)
main()
